    normen: ["§ 124 Abs. 1 und Abs. 2 AO", "§ 125 Abs. 1 AO", "§ 122 Abs. 1 AO", "§ 355 AO", "§ 362 AO", "§ 85 AO", "§ 120 Abs. 1 AO", "§ 164 Abs. 1 bis 4 AO", "§ 165 Abs. 2 AO", "§§ 167, 168 AO", "§ 129 AO", "§ 172 Abs. 1 Satz 1 Nr. 2a und 2c AO", "§ 173 Abs. 1 Nr. 1 und Nr. 2 AO", "§ 173a AO", "§ 174 Abs. 1 bis 4 AO", "§ 175 Abs. 1 Satz 1 Nr. 1 und Nr. 2 AO", "§ 177 AO", "§ 169 Abs. 1 Satz 1 AO", "§ 171 Abs. 1 Satz 2, Abs. 2 und Abs. 3, Abs. 10 AO", "§ 367 Abs. 2 Satz 3 AO", "§ 37 EStG", "§ 41a EStG", "§ 18 Abs. 1 und 2 UStG", "§§ 16, 17 EStG", "AEAO vor §§ 172 bis 177 AO"],
