    normen: ["§ 129 AO", "§ 173 Abs. 1 Nr. 2 AO", "§ 173a AO", "§ 171 Abs. 2 Sätze 1 und 2 AO", "§ 171 Abs. 3 AO", "§ 15 Abs. 1 Satz 1 Nr. 1 EStG", "§ 33a Abs. 1 EStG"],
    themen: ["Fallbeispiel", "Additionsfehler", "Zahlendreher", "Festsetzungsverjährung", "Ablaufhemmung"],
